:root {
  --bg: #fffbf7;
  --card-bg: #ffffff;
  --text: #2d2327;
  --text-muted: #6b5b62;
  --coral: #e05a47;
  --coral-dark: #b84332;
  --ink: #1a1617;
  --cream: #fcf6f0;
  --border: #e6d5cc;
  --radius: 16px;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  padding: 1.5rem;
}
.container { max-width: 900px; margin: 0 auto; }
header { margin-bottom: 2rem; text-align: center; }
h1 { font-size: 2.25rem; color: var(--ink); margin-bottom: 0.5rem; font-weight: 800; letter-spacing: -0.02em; }
p.subtitle { color: var(--text-muted); }
.nav-tabs { display: flex; justify-content: center; gap: 0.5rem; margin-bottom: 1.5rem; }
.tab-btn {
  background: var(--cream);
  color: var(--text-muted);
  border: 1px solid var(--border);
  padding: 0.5rem 1.25rem;
  border-radius: 20px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}
.tab-btn.active { background: var(--coral); color: white; border-color: var(--coral); }
.card {
  background: var(--card-bg);
  border: 2px solid var(--ink);
  border-radius: var(--radius);
  padding: 1.75rem;
  margin-bottom: 1.5rem;
  box-shadow: 4px 4px 0px var(--ink);
}
h2 { font-size: 1.35rem; color: var(--ink); margin-bottom: 1rem; display: flex; align-items: center; gap: 0.5rem; }
label { font-size: 0.875rem; font-weight: 700; margin-bottom: 0.375rem; color: var(--ink); display: block; }
input {
  width: 100%;
  padding: 0.75rem;
  border: 2px solid var(--ink);
  border-radius: 8px;
  background: var(--cream);
  font-size: 1rem;
  color: var(--text);
  font-weight: 600;
}
input:focus { outline: none; border-color: var(--coral); }
.field { display: flex; flex-direction: column; margin-bottom: 1rem; }
.btn-row { display: flex; gap: 1rem; margin-top: 1rem; flex-wrap: wrap; }
button.primary {
  background: var(--coral);
  color: white;
  border: 2px solid var(--ink);
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 2px 2px 0px var(--ink);
}
button.primary:hover:not(:disabled) { transform: translate(-1px, -1px); box-shadow: 3px 3px 0px var(--ink); }
button:disabled { opacity: 0.5; cursor: not-allowed; box-shadow: none; }
.notice {
  background: #fff3cd;
  color: #856404;
  border: 2px solid var(--ink);
  padding: 0.75rem;
  border-radius: 8px;
  margin-bottom: 1rem;
  font-size: 0.875rem;
  font-weight: 600;
}
.feedback-box { padding: 1rem; border-radius: 8px; border: 2px solid var(--ink); margin-top: 1rem; font-weight: 700; text-align: center; }
.feedback-box.correct { background: #d4edda; color: #155724; }
.feedback-box.incorrect { background: #f8d7da; color: #721c24; }
table { width: 100%; border-collapse: collapse; margin-top: 1rem; }
th, td { padding: 0.75rem; text-align: left; border-bottom: 2px solid var(--border); font-size: 0.95rem; }
th { font-weight: 700; color: var(--ink); background: var(--cream); }
.empty-state { color: var(--text-muted); text-align: center; padding: 2rem; font-weight: 600; }
.quiz-card { background: var(--cream); border: 2px dashed var(--ink); padding: 1.25rem; border-radius: 12px; margin-bottom: 1rem; }

